[
  {
    "statement": "There are no studies that have directly evaluated the effects of breeding bats in captivity to supplement wild populations affected by white-nose syndrome.",
    "citations": []
  },
  {
    "statement": "Systematic searches have not found any studies assessing the success rate of reintroducing captive-bred bats into areas affected by white-nose syndrome.",
    "citations": []
  },
  {
    "statement": "Evidence on breeding bats in captivity shows that reproductive success varies, with 6-100% of female bats successfully conceiving and giving birth.",
    "citations": []
  },
  {
    "statement": "The survival rates of captive-born bat pups range from 20-100%.",
    "citations": []
  },
  {
    "statement": "Studies on the reproductive success and survival rates of captive-bred bats do not address the specific challenge of reintroducing the bats into areas affected by white-nose syndrome.",
    "citations": []
  },
  {
    "statement": "Rehabilitation studies show that hand-reared orphaned bats have survival rates of 70-90% for at least 4-14 days after release into the wild.",
    "citations": []
  },
  {
    "statement": "There is some evidence of longer-term survival for hand-reared orphaned bats, with some surviving up to nearly four years.",
    "citations": []
  },
  {
    "statement": "The survival data from rehabilitation studies is for rehabilitated bats, not for captive-bred individuals.",
    "citations": []
  }
]

[
  {
    "statement": "There is no available evidence regarding the effectiveness of training arborists and forestry operatives to identify potential bat roosts.",
    "citations": [
      "1981"
    ]
  },
  {
    "statement": "There is no available evidence regarding the effectiveness of protecting roost trees during forest operations.",
    "citations": [
      "1982"
    ]
  },
  {
    "statement": "No studies have been found that evaluated the effects on bat populations of training arborists and forestry operatives to identify potential bat roosts.",
    "citations": [
      "1981"
    ]
  },
  {
    "statement": "No studies have been found that evaluated the effects on bat populations of protecting roost trees during forest operations.",
    "citations": [
      "1982"
    ]
  },
  {
    "statement": "The evidence base for training arborists to identify bat roosts and for protecting roost trees during forest operations is currently insufficient to determine which approach would be more effective.",
    "citations": [
      "1981",
      "1982"
    ]
  }
]
